create extension if not exists pgtap with schema extensions;
begin;
select no_plan();
select set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"90000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select ok(not has_function_privilege('anon','public.enable_all_notifications_v1(uuid,text,jsonb,text)','execute'),'guests cannot enable notifications for an account');
select ok(has_function_privilege('authenticated','public.enable_all_notifications_v1(uuid,text,jsonb,text)','execute'),'authenticated users can save their device permission');
update private.push_control set enabled=true,general_release=true;
select public.get_notification_preferences_v1();
update private.notification_preferences set activity=false,academic=false,announcement=false,account=false,reminder=false where user_id=auth.uid();
select set_config('t.sub',jsonb_build_object('endpoint','https://fcm.googleapis.com/fcm/send/simple-consent','keys',jsonb_build_object('p256dh',repeat('A',87),'auth',repeat('B',22)))::text,true);
select throws_ok($q$select public.enable_all_notifications_v1('90000000-0000-4000-8000-000000000002','simple-device',current_setting('t.sub')::jsonb,'UTC')$q$,'PT403',null,'stale consent cannot enable a different signed-in account');
select is((select count(*)::int from public.push_tokens where device_key='simple-device'),0,'cross-account failure does not register a token');
select throws_ok($q$select public.enable_all_notifications_v1(auth.uid(),'simple-device','{"endpoint":"https://attacker.test"}','UTC')$q$,'PT422',null,'invalid subscription rejected before preferences change');
select ok((select not(activity or academic or announcement or account or reminder) from private.notification_preferences where user_id=auth.uid()),'failed enable leaves preferences unchanged');
select lives_ok($q$select public.enable_all_notifications_v1(auth.uid(),'simple-device',current_setting('t.sub')::jsonb,'Europe/London')$q$,'one consent enables a valid browser subscription');
select ok((select activity and academic and announcement and account and reminder from private.notification_preferences where user_id=auth.uid()),'all categories and daily reminder enabled together');
select is((select timezone from private.notification_preferences where user_id=auth.uid()),'Europe/London','timezone is detected automatically');
select is((select reminder_time::text from private.notification_preferences where user_id=auth.uid()),'19:00:00','automatic daily reminder defaults to seven pm');
select lives_ok($q$select public.enable_all_notifications_v1(auth.uid(),'simple-device',current_setting('t.sub')::jsonb,'not/a-zone')$q$,'unsupported browser timezone falls back safely');
select is((select timezone from private.notification_preferences where user_id=auth.uid()),'Africa/Lagos','timezone fallback is Africa/Lagos');
select is((select count(*)::int from public.push_tokens where device_key='simple-device' and revoked_at is null),1,'repeating enable does not create extra active device records');
select public.revoke_push_token_v1('web','simple-device');
select ok(not exists(select 1 from public.push_tokens where device_key='simple-device' and revoked_at is null),'single off action revokes this device');
select ok((select delivery_config='{}'::jsonb from public.push_tokens where device_key='simple-device'),'turning off clears device credentials');
select * from finish();
rollback;
